# Crop real page captures into clippings (nothing altered) + highlight boxes in clip px (from capture.mjs rects x1.5).
import json, os
from PIL import Image
D = os.path.abspath(os.path.join(os.path.dirname(__file__), '..')); S = os.path.join(D, '_src'); O = os.path.join(S, 'clips')
def clip(name, src, box, hls, source, date, url):
    x0, y0, x1, y1 = box; Image.open(os.path.join(S, src)).convert('RGB').crop(box).save(os.path.join(O, name + '.png'))
    return name, {'file': 'clips/' + name + '.png', 'w': x1 - x0, 'h': y1 - y0, 'hl': [[x - x0 - 4, y - y0 - 2, w + 8, h + 6] for x, y, w, h in hls], 'source': source, 'date': date, 'url': url}
SIE = 'https://studyinestonia.ee/working'; RT = 'https://www.riigiteataja.ee/en/eli/523052019003/consolide'
RT25 = 'https://www.riigiteataja.ee/akt/130012025002'; RTS = 'riigiteataja.ee, Adult Education Act § 13 (in force since 1 Apr 2025)'
out = dict([
  clip('sie-hours', 'sie-working__not-limited.png', (470, 700, 1000, 815), [(520, 777, 112, 24)], 'studyinestonia.ee, Working', '2 Nov 2026', SIE),
  clip('sie-balance', 'sie-working__around-30-ects-credit-po.png', (470, 670, 1830, 900), [(830, 777, 469, 24), (823, 867, 805, 24)], 'studyinestonia.ee, Working', '2 Nov 2026', SIE),
  clip('sie-ects', 'sie-working__around-30-ects-credit-po.png', (560, 760, 1306, 803), [(830, 777, 469, 24)], 'studyinestonia.ee, Working', '2 Nov 2026', SIE),
  clip('sie-hard', 'sie-working__around-30-ects-credit-po.png', (476, 850, 1640, 893), [(823, 867, 805, 24)], 'studyinestonia.ee, Working', '2 Nov 2026', SIE),
  clip('rt-30', 'rt-aea__up-to-thirty-calendar-da.png', (180, 773, 516, 808), [(186, 778, 320, 26)], 'riigiteataja.ee, Adult Education Act § 13', '2 Nov 2026', RT),
  clip('rt-20', 'rt-aea__up-to-thirty-calendar-da.png', (636, 983, 1142, 1019), [(911, 988, 228, 26)], 'riigiteataja.ee, Adult Education Act § 13', '2 Nov 2026', RT),
  clip('rt-leave', 'rt-aea__up-to-thirty-calendar-da.png', (170, 665, 1640, 1050), [(186, 778, 320, 26), (911, 988, 228, 26)], 'riigiteataja.ee, Adult Education Act § 13', '2 Nov 2026', RT),
  clip('rt13-30', 'rt-tks-2025__15-kalendrip-eva.png', (176, 388, 1636, 556), [(726, 467, 407, 24)], RTS, '2 Nov 2026', RT25),
  clip('rt13-20', 'rt-tks-2025__15-kalendrip-eva.png', (176, 672, 1636, 734), [(550, 708, 206, 24)], RTS, '2 Nov 2026', RT25),
  clip('rt13-15', 'rt-tks-2025__15-kalendrip-eva.png', (176, 776, 1636, 808), [(564, 782, 393, 24)], RTS, '2 Nov 2026', RT25),
  clip('rt13-leave', 'rt-tks-2025__15-kalendrip-eva.png', (176, 388, 1636, 808), [(726, 467, 407, 24), (550, 708, 206, 24), (564, 782, 393, 24)], RTS, '2 Nov 2026', RT25),
  clip('tt-45', 'taltech2__45-ects.png', (120, 764, 1792, 868), [(747, 780, 880, 26)], 'taltech.ee, Settling In', '2 Nov 2026', 'https://taltech.ee/en/practical'),
  clip('tt-cancel', 'taltech2__45-ects.png', (120, 624, 1792, 724), [(445, 690, 252, 26)], 'taltech.ee, Settling In', '2 Nov 2026', 'https://taltech.ee/en/practical'),
  clip('sie-hours-p', 'sie-working__not-limited.png', (470, 760, 700, 812), [(520, 777, 112, 24)], 'studyinestonia.ee, Working', '2 Nov 2026', SIE),
  clip('sie-ects-p', 'sie-working__around-30-ects-credit-po.png', (827, 766, 1306, 802), [(830, 777, 469, 24)], 'studyinestonia.ee, Working', '2 Nov 2026', SIE),
  clip('rt13-30-p', 'rt-tks-2025__15-kalendrip-eva.png', (723, 460, 1142, 498), [(726, 467, 407, 24)], RTS, '2 Nov 2026', RT25),
  clip('tt-45-p', 'taltech2__45-ects.png', (1096, 772, 1632, 812), [(1095, 780, 532, 26)], 'taltech.ee, Settling In', '2 Nov 2026', 'https://taltech.ee/en/practical'),
  clip('tt-cancel-p', 'taltech2__45-ects.png', (399, 680, 712, 722), [(445, 690, 252, 26)], 'taltech.ee, Settling In', '2 Nov 2026', 'https://taltech.ee/en/practical'),
])
json.dump(out, open(os.path.join(O, 'clips.json'), 'w'), indent=1)
open(os.path.join(D, '_shared', 'clips.js'), 'w').write('/* generated by _tools/clips.py */\nconst CLIPS = ' + json.dumps(out) + ';\n'); print('ok', list(out))
